179		readonly removed?: ResourceSet;
180	}
181	
182	function computeItemsDelta(oldItems: ResourceMap<vscode.ChatSessionItem>, newItems: ResourceMap<vscode.ChatSessionItem>): ChatSessionDelta {
183		const delta = {
184			addedOrUpdated: new ResourceMap<vscode.ChatSessionItem>(),
185			removed: new ResourceSet(),
186		} satisfies ChatSessionDelta;
187	
188		for (const [newResource, newItem] of newItems) {
189			const oldItem = oldItems.get(newResource);
190			if (oldItem !== newItem) {
191				delta.addedOrUpdated.set(newResource, newItem);
192			}
193		}
194	
195		for (const oldResource of oldItems.keys()) {
196			if (!newItems.has(oldResource)) {
197				delta.removed.add(oldResource);
198			}
199		}
200	
201		return delta;
202	}
203	
204	function convertChatSessionDeltaToDto(delta: ChatSessionDelta): { addedOrUpdated: ReturnType<typeof typeConvert.ChatSessionItem.from>[]; removed: URI[] } {
205		return {
206			addedOrUpdated: delta.addedOrUpdated ? Array.from(delta.addedOrUpdated.values(), typeConvert.ChatSessionItem.from) : [],
207			removed: delta.removed ? Array.from(delta.removed.keys()) : []
208		};
209	}
