	async $forkChatSession(handle: number, sessionResourceComponents: UriComponents, request: IChatSessionRequestHistoryItemDto | undefined, token: CancellationToken): Promise<ReturnType<typeof typeConvert.ChatSessionItem.from>> {
		const sessionResource = URI.revive(sessionResourceComponents);

		const requestTurn = request ? new extHostTypes.ChatRequestTurn(
			request.prompt,
			request.command,
			[],
			request.participant,
			[],
			undefined,
			request.id,
			request.modelId,
		) : undefined;

		// Prefer the controller's fork handler over the session's deprecated fork handler.
		const controller = this._getForkController(sessionResource.scheme);
		if (controller?.forkHandler) {
			return typeConvert.ChatSessionItem.from(await controller.forkHandler(sessionResource, requestTurn, token));
		}

		const session = this._extHostChatSessions.get(sessionResource)?.sessionObj.session;
		if (session?.forkHandler) {
			return typeConvert.ChatSessionItem.from(await session.forkHandler(requestTurn, token));
		}

		throw new Error(`Chat session ${sessionResource} does not support forking`);
	}

