420		createChatSessionItemController(extension: IExtensionDescription, id: string, refreshHandler: (token: vscode.CancellationToken) => Thenable<void>): vscode.ChatSessionItemController {
421			const controllerHandle = this._itemControllerHandlePool++;
422			const disposables = new DisposableStore();
423	
424			let isDisposed = false;
425			let newChatSessionItemHandler: vscode.ChatSessionItemController['newChatSessionItemHandler'];
426			const onDidChangeChatSessionItemStateEmitter = disposables.add(new Emitter<vscode.ChatSessionItem>());
427	
428			const collection = new ChatSessionItemCollectionImpl(controllerHandle, this._proxy);
429	
430			const controller = Object.freeze<vscode.ChatSessionItemController>({
431				id,
432				refreshHandler: async (refreshToken: CancellationToken) => {
433					if (isDisposed) {
434						throw new Error('ChatSessionItemController has been disposed');
435					}
436	
437					this._logService.trace(`ExtHostChatSessions. Controller(${id}).refresh()`);
438					await refreshHandler(refreshToken);
439				},
440				items: collection,
441				onDidChangeChatSessionItemState: onDidChangeChatSessionItemStateEmitter.event,
442				createChatSessionItem: (resource: vscode.Uri, label: string) => {
443					if (isDisposed) {
444						throw new Error('ChatSessionItemController has been disposed');
445					}
446	
447					const item = new ChatSessionItemImpl(resource, label, () => {
448						// Make sure the item really is in the collection. If not we don't need to transmit it to the main thread yet
449						if (collection.get(resource) === item) {
450							void this._proxy.$addOrUpdateChatSessionItem(controllerHandle, typeConvert.ChatSessionItem.from(item));
451						}
452					});
453					return item;
454				},
455				get newChatSessionItemHandler() { return newChatSessionItemHandler; },
456				set newChatSessionItemHandler(handler: vscode.ChatSessionItemController['newChatSessionItemHandler']) { newChatSessionItemHandler = handler; },
457				dispose: () => {
458					isDisposed = true;
459					disposables.dispose();
460				},
461			});
462	
463			this._chatSessionItemControllers.set(controllerHandle, { controller, extension, disposable: disposables, chatSessionType: id, onDidChangeChatSessionItemStateEmitter });
464	
465			// Register the controller with the main thread
466			this._proxy.$registerChatSessionItemController(controllerHandle, id);
467	
468			disposables.add(toDisposable(() => {
469				this._chatSessionItemControllers.delete(controllerHandle);
470				this._proxy.$unregisterChatSessionItemController(controllerHandle);
471			}));
472	
473			return controller;
474		}

